describe('list rows under any envelope', () => {
  it('the declared path first, then the body, then the usual keys', () => {
    expect(listRows({ page: { rows: [1, 2] } }, 'page.rows')).toEqual([1, 2]);
    expect(listRows([3], 'missing')).toEqual([3]);
    for (const key of ['records', 'data', 'items', 'content', 'results']) expect(listRows({ [key]: [key] }, '')).toEqual([key]);
    expect(listRows({ page: 'x' }, 'page.rows.deep')).toEqual([]);
    expect(listRows(null, 'a')).toEqual([]);
    expect(listRows('text', '')).toEqual([]);
  });
  it('maps the rows of a list response, however it is wrapped', () => {
    const twice = (d: Record<string, unknown>) => Number(d.n) * 2;
    expect(mapList([{ n: 1 }], twice)).toEqual([2]);
    expect(mapList({ items: [{ n: 2 }] }, twice)).toEqual([4]);
    expect(mapList({ other: [{ n: 2 }] }, twice)).toEqual([]);
    expect(mapList(7, twice)).toEqual([]);
  });
});

describe('Android text on whole pixels', () => {
  const styleOf = (el: React.ReactElement) => {
    const tree = mount(el);
    // by predicate: findByType's ElementType is typed against the renderer's own copy of React's types, which older SDKs pin apart
    const style = tree.root.findAll((n) => n.type === (Text as unknown))[0]!.props.style;
    act(() => tree.unmount());
    return style;
  };
  beforeEach(() => {
    jest.replaceProperty(Platform, 'OS', 'android');
    jest.spyOn(PixelRatio, 'get').mockReturnValue(2.88);
    jest.spyOn(PixelRatio, 'getFontScale').mockReturnValue(1);
  });
  afterEach(() => {
    jest.restoreAllMocks();
  });
  it('hands Android a size just under the nearest pixel, so its ceiling lands there', () => {
    const style = styleOf(<Txt style={{ fontSize: 14 }}>x</Txt>);
    expect(Array.isArray(style)).toBe(true);
    expect(style[1].fontSize).toBeCloseTo((40 - 0.01) / 2.88, 6);
  });
  it('leaves a size that already lands on a pixel, or none at all, as it is', () => {
    expect(styleOf(<Txt style={{ fontSize: 12.5 }}>x</Txt>)).toEqual({ fontSize: 12.5 });
    expect(styleOf(<Txt style={{ color: 'red' }}>x</Txt>)).toEqual({ color: 'red' });
    expect(styleOf(<Txt style={{ fontSize: 0 }}>x</Txt>)).toEqual({ fontSize: 0 });
  });
  it('reads the font scale only when the text scales, capped by its multiplier', () => {
    jest.spyOn(PixelRatio, 'getFontScale').mockReturnValue(3);
    expect(Array.isArray(styleOf(<Txt style={{ fontSize: 14 }} allowFontScaling={false}>x</Txt>))).toBe(true);
    expect(styleOf(<Txt style={{ fontSize: 14 }} maxFontSizeMultiplier={0.5}>x</Txt>)).toBeDefined();
  });
});

